<section class="card"><div class="table-wrap"><table><thead><tr><th>Harvest ID</th><th>Farm</th><th>Crop</th><th>Date</th><th>Quantity kg</th><th>PHP/kg</th><th>Grade</th><th>Remark</th><th>Actions</th></tr></thead><tbody>
